test('createInvoice rejects discountPercent below 0', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -1 }],
  }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects discountPercent above 100', () => {
  assert.deepEqual(createInvoice({
